CustomField.formula:
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__ProdTotalCPCColorLineItem__c > 0 ,
TSGCFG__ProdSumofCPCColor2__c / TSGCFG__ProdTotalCPCColorLineItem__c,
IF( ABS(TSGCFG__ProdTotalColor2Volume__c - TSGCFG__Prod_Total_Volume_Includes_Color_2__c)<>0, TSGCFG__ProdTotalColor2MonthlyCost__c /  ABS(TSGCFG__ProdTotalColor2Volume__c - TSGCFG__Prod_Total_Volume_Includes_Color_2__c),
IF( TSGCFG__ProdTotalCPCColorLineItem__c > 0, TSGCFG__ProdSumofCPCColor2__c / TSGCFG__ProdTotalCPCColorLineItem__c, 0
)
)
)
